import { Column, Model, Table, HasMany } from 'sequelize-typescript';
import { Injectable } from '@nestjs/common';
import { InjectModel } from '@nestjs/sequelize';

@Table
export class User extends Model {
  @Column
  firstName: string;

  @Column({ defaultValue: true })
  isActive: boolean;

  @HasMany(() => Photo)
  photos: Photo[];
}

@Injectable()
export class UsersService {
  constructor(@InjectModel(User) private userModel: typeof User) {}
}

async createMany() {
  await this.sequelize.transaction(async (t) => {
    const transactionHost = { transaction: t };

    await this.userModel.create(
      { firstName: 'Abraham', lastName: 'Lincoln' },
      transactionHost,
    );
    await this.userModel.create(
      { firstName: 'John', lastName: 'Booth' },
      transactionHost,
    );
  });
}

import { Module, Inject, Injectable } from '@nestjs/common';
import { CacheModule, CACHE_MANAGER, Cache } from '@nestjs/cache-manager';

@Module({
  imports: [CacheModule.register({ ttl: 5000, isGlobal: true })],
})
export class AppModule {}

@Injectable()
export class UsersService {
  constructor(@Inject(CACHE_MANAGER) private cacheManager: Cache) {}

  async findOne(id: string) {
    const cached = await this.cacheManager.get('user:' + id);
    if (cached) return cached;
    const user = await this.load(id);
    await this.cacheManager.set('user:' + id, user, 10_000);
    return user;
  }
}

